import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[][] cost = new long[(int) n][(int) n];
        for (int i = 0; i < cost.length; i++) {
            for (int j = 0; j < cost[i].length; j++) {
                cost[i][j] = Long.parseLong(next());
            }
        }

        final long INF = 1000000000000000000L;
        int tasks = (int) n;
        int full = (1 << tasks) - 1;
        long[] best = new long[1 << tasks];
        Arrays.fill(best, INF);
        best[0] = 0;
        for (int mask = 0; mask < full; mask++) {
            long cur = best[mask];
            if (cur == INF) continue;
            int k = Integer.bitCount(mask);
            for (int j = 0; j < tasks; j++) {
                if ((mask >> j & 1) != 0) continue;
                int nm = mask | (1 << j);
                best[nm] = Math.min(best[nm], cur + cost[k][j]);
            }
        }
        System.out.println(best[full]);
    }
}
